// === Tab: mySketch ===
let g;
let frac = 6
let	scaleX = 0.8
let	radius, sqrt3, deg120

function setup() {
	createCanvas(windowHeight, windowHeight)
	imageMode(CENTER)
	stroke(240, 250, 255, 80)
	noFill()
  radius = height / 3
  sqrt3 = sqrt(3)
  deg120 = (PI / 3) * 2
	createGUI()

	g = createGraphics(int(windowHeight), int(windowHeight))
	g.noFill()
	g.stroke(240, 250, 255, 80)
	g.translate(windowHeight / 2, windowHeight / 2)

	run()
}

function mouseMoved() {
	scaleX = map((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), 0, width, -0.1, 0.5) + map((window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))), 0, height, -0.1, 0.7)
	run()
}

function run() {
	g.clear()
	tri(0, cos(deg120) * radius, sin(deg120) * radius, cos(deg120 * 2) * radius, sin(deg120 * 2) * radius, cos(deg120 * 3) * radius, sin(deg120 * 3) * radius)

	background(0)
	for (let y = 0; y < 2; y += 1) {
		for (let x = 0; x < 3; x += 1) {
			draw_triangle(x * radius * sqrt3, radius + y * height / 2, PI / 6)
			if (x != 2) draw_triangle(x * radius * sqrt3 + radius * sqrt3 * 0.5, radius - (radius / 2) + y * height / 2, PI / 6 + PI / 3)
		}
	}
}

function draw_triangle(x, y, angle) {
	push()
	translate(x, y)
	rotate(angle)
	image(g, 0, 0)
	pop()
}

function tri(n, x1, y1, x2, y2, x3, y3) {
	if (n == frac) {
		g.triangle(x1, y1, x2, y2, x3, y3)
		return
	}
	const _x1 = (x2 - x3) * scaleX + x3
	const _y1 = (y2 - y3) * scaleX + y3
	const _x2 = (x3 - x1) * scaleX + x1
	const _y2 = (y3 - y1) * scaleX + y1
	const _x3 = (x1 - x2) * scaleX + x2
	const _y3 = (y1 - y2) * scaleX + y2
	tri(n + 1, x1, y1, _x3, _y3, _x2, _y2)
	tri(n + 1, x2, y2, _x1, _y1, _x3, _y3)
	tri(n + 1, x3, y3, _x2, _y2, _x1, _y1)
	tri(n + 1, _x1, _y1, _x2, _y2, _x3, _y3)
}

function createGUI() {
   const p_font_size = "16px"
